client_script:
var doc = frappe.web_form && frappe.web_form.doc;
if (doc && doc.name) {
	var $actions = $(".web-form-header .web-form-actions").first();
	if ($actions.length && !$actions.find(".btn-leave-group").length) {
		var $leave = $('<button type="button" class="btn btn-default btn-sm ml-2 btn-leave-group"></button>').text(__("Leave this group"));
		$actions.append($leave);
		$leave.on("click", function (e) {
			e.preventDefault();
			frappe.confirm(__("Leave {0}? A leader can add you again.", [doc.group_name]), function () {
				frappe.call({
					method: "churchit.church_people.group_api.leave_group",
					type: "POST",
					args: { group: doc.name },
					freeze: true,
					callback: function (r) {
						if (r.message) {
							window.location.href = "/groups";
						}
					}
				});
			});
		});
	}
}
